def esc(v): return html.escape(str(v), quote=True)
def link(key):
    label,url=sources[key]
    return '<a target="_blank" rel="noopener noreferrer" href="'+esc(url if url.startswith('https:') else BASE+url)+'">'+esc(label)+'</a>'
def code_link(path):
    assert (ROOT/path).is_file(), path
    return '<a target="_blank" rel="noopener noreferrer" href="'+esc(BASE+path)+'"><code>'+esc(path)+'</code></a>'
for label,url in sources.values():
    if not url.startswith('https:'): assert (ROOT/url).is_file(),url
