script='''
const all=[...document.querySelectorAll('.question')], search=document.querySelector('#search'),group=document.querySelector('#group'),mode=document.querySelector('#mode'),topic=document.querySelector('#topic');
let learned=new Set();try{learned=new Set(JSON.parse(localStorage.getItem('somi-study-v1')||'[]'))}catch{}
function norm(s){return s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase()}
function render(){const term=norm(search.value);let visible=0;all.forEach(el=>{const id=Number(el.id.slice(1)),done=learned.has(id);const show=(!group.value||el.dataset.group===group.value)&&(!topic.value||el.dataset.topic===topic.value)&&norm(el.textContent).includes(term)&&(mode.value!=='todo'||!done);el.hidden=!show;if(show)visible++;const b=el.querySelector('.mark');b.setAttribute('aria-pressed',String(done));b.textContent=done?'✓ Đã ôn':'Đánh dấu đã ôn'});document.querySelector('#status').textContent=`${visible}/${all.length} câu đang hiển thị · Đã ôn ${learned.size}/${all.length}`;document.querySelector('#empty').hidden=visible>0}
[search,group,mode,topic].forEach(el=>el.addEventListener('input',render));document.querySelectorAll('.mark').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.id);learned.has(n)?learned.delete(n):learned.add(n);try{localStorage.setItem('somi-study-v1',JSON.stringify([...learned]))}catch{}render()}));
document.querySelector('#expand').addEventListener('click',()=>all.filter(x=>!x.hidden).forEach(x=>x.querySelector('details').open=true));document.querySelector('#collapse').addEventListener('click',()=>all.forEach(x=>x.querySelector('details').open=false));document.querySelector('#random').addEventListener('click',()=>{const pool=all.filter(x=>!x.hidden);if(pool.length){const el=pool[Math.floor(Math.random()*pool.length)];el.querySelector('details').open=true;el.scrollIntoView({behavior:'smooth',block:'start'})}});
document.querySelector('#print').addEventListener('click',()=>{all.filter(x=>!x.hidden).forEach(x=>x.querySelector('details').open=true);window.print()});window.addEventListener('beforeprint',()=>all.filter(x=>!x.hidden).forEach(x=>x.querySelector('details').open=true));
function hash(){const el=document.getElementById(location.hash.slice(1));if(el&&el.classList.contains('question')){group.value='';topic.value='';search.value='';mode.value='';render();el.querySelector('details').open=true;el.scrollIntoView()}}window.addEventListener('hashchange',hash);document.querySelectorAll('.topic-jump').forEach(a=>a.addEventListener('click',()=>{group.value=a.dataset.owner;topic.value=a.dataset.topic;search.value='';mode.value='';render()}));render();hash();
'''
doc=f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Bộ ôn bảo vệ SOMI: chức năng, kiến thức, câu hỏi và đáp án theo ba thành viên, có nguồn code và API."><title>SOMI · Bộ ôn bảo vệ project</title><style>{styles}</style></head><body>
<header><div class="eyebrow">Somi Grab Delivery / Study handbook</div><h1>Hiểu chức năng.<br>Nắm code. Tự tin bảo vệ.</h1><p>Bộ kiến thức và câu hỏi–đáp án cho Anh Thư, Nhi, Minh Anh. Chia theo phân công trong báo cáo, đối chiếu source PHP hiện tại; có dẫn nguồn cho từng câu.</p><div class="pills"><span class="pill">{len(qa)} câu hỏi có đáp án</span><span class="pill">3 phần phụ trách</span><span class="pill">HTML độc lập · Dùng offline</span><span class="pill">15/11/2026 · Asia/Saigon</span></div></header>
<main><nav class="nav" aria-label="Mục lục"><a href="#scope">Phân công & chức năng</a><a href="#knowledge">Kiến thức cần nắm</a><a href="#questions">Bộ câu hỏi</a><a href="#apis">Bảng API</a><a href="#demo">Kịch bản demo</a><a href="#sources">Nguồn</a></nav>
<aside class="notice"><b>Đọc trước khi ôn</b><p>Google Docs có tab bìa t.0 của tài liệu khác và tab báo cáo SOMI chứa phân công ba người. Bộ này lấy phân công Anh Thư / Nhi / Minh Anh ở tab SOMI. Không suy diễn tên người từ số Người 1/2/3 của ownership backend.</p><p>Báo cáo có mô tả React/Vite, VIETMAP/VNPAY và backend còn dự kiến; source hiện tại đã là PHP, có Bootstrap/OOP và adapter Geoapify/SePay/Resend. Các chức năng dưới đây là phạm vi thể hiện trong source/contract, <b>không phải xác nhận mọi luồng đã nghiệm thu production</b>. Refund/payout còn thủ công và cần đối soát; USD checkout khóa.</p><p>Nguồn: {link('report')} · {link('own')} · {link('oop')}</p></aside>
<section id="scope"><h2>01 / Ai làm phần nào? Web có chức năng gì?</h2><p>Phân công thuyết trình theo báo cáo. Mỗi người nắm sâu phần giao diện/nghiệp vụ của mình và hiểu điểm nối sang service chung. Link dưới từng nhóm dẫn đến file thực tế.</p><div class="grid">{featurehtml}</div></section>
<section id="knowledge"><h2>02 / Kiến thức cả nhóm cần nắm</h2><div class="panel"><p><b>Kiến trúc:</b> trình duyệt → PHP view/JavaScript → API endpoint → kiểm session, quyền, dữ liệu → service/entity/repository → PostgreSQL hoặc provider → JSON → cập nhật giao diện.</p><div class="flow"><span>Báo giá</span><span>Tạo đơn</span><span>Thanh toán xác nhận</span><span>Tìm shipper</span><span>Nhận đơn</span><span>Lấy hàng</span><span>Đang giao</span><span>Giao thành công</span></div><p><b>Trạng thái code:</b> PENDING_PAYMENT → SEARCHING_SHIPPER → SHIPPER_ASSIGNED → PICKED_UP → IN_DELIVERY → DELIVERED. Các nhánh khác: NO_SHIPPER_FOUND, CANCELLED, RETURNING → RETURNED. ARRIVED là mốc giao nhận, không phải trạng thái Order.</p><p><b>Khái niệm:</b> OOP/đóng gói/kế thừa; MVC-style; HTTP/HTTPS, GET/POST, JSON/fetch; session và phân quyền; prepared statement; transaction/lock/idempotency; snapshot; callback/webhook; queue/retry; responsive và i18n.</p><p><b>Cách trả lời:</b> Chức năng phục vụ ai → dữ liệu đầu vào → endpoint/hàm chính → kiểm tra quyền/điều kiện → thay đổi DB → đầu ra/lỗi → test một nhánh thành công và một nhánh thất bại. Phần hỏi sâu trong mỗi đáp án dùng để luyện mở code.</p><p>{link('order')} · {link('readme')} · {link('kernel')}</p></div></section>
<section id="questions"><h2>03 / Bộ câu hỏi & đáp án gợi ý</h2><p>Chọn tên để ôn phần riêng; cả ba cùng học “Cả nhóm” và “API & tích hợp”. Có thêm 60 câu chuyên sâu chia đủ 15 nhóm chức năng: mỗi câu có đáp án, hàm cần mở, tình huống kiểm tra và câu hỏi xoáy. Đây là câu ôn dự kiến, không cam kết giảng viên sẽ hỏi. Đánh dấu chỉ lưu trên trình duyệt đang dùng, không đồng bộ cho người khác.</p><div class="toolbar"><input id="search" type="search" placeholder="Tìm câu hỏi, API, hàm… (có thể gõ không dấu)" aria-label="Tìm câu hỏi"><select id="group" aria-label="Phần phụ trách"><option value="">Tất cả phần</option>{''.join('<option>'+esc(g)+'</option>' for g in groups)}</select><select id="topic" aria-label="Nhóm chức năng"><option value="">Mọi chức năng</option>{''.join('<option>'+esc(t)+'</option>' for t in dict.fromkeys(x.get('topic') for x in qa if x.get('topic')))}</select><select id="mode" aria-label="Tiến độ"><option value="">Mọi câu</option><option value="todo">Chưa ôn</option></select><button id="expand">Mở đáp án</button><button id="collapse">Thu gọn</button><button id="random">Bốc câu</button><button id="print">In / Lưu PDF</button></div><div id="status" class="status" aria-live="polite"></div><p class="printnote">Mẹo: lọc theo người rồi bấm In / Lưu PDF để xuất bộ riêng. File HTML tự chứa giao diện và dữ liệu, không cần npm hoặc server.</p>{''.join(cards)}<p id="empty" class="empty" hidden>Không có câu phù hợp. Hãy đổi bộ lọc.</p><noscript>JavaScript đang tắt. Bạn vẫn mở từng câu bằng cách bấm vào tiêu đề; bộ lọc và tiến độ cần JavaScript.</noscript></section>
<section id="apis"><h2>04 / Bảng API nội bộ cần nhớ</h2><p>Base URL: <code>/public/api/</code>. Bảng là bản tóm tắt để ôn; xem contract và endpoint liên kết để biết trường bắt buộc, action và permission. API ứng dụng khác với API dịch vụ bên ngoài.</p><div class="tablewrap"><table><thead><tr><th>Vai trò</th><th>Method + endpoint</th><th>Ý nghĩa / nguồn</th></tr></thead><tbody>{apihtml}</tbody></table></div></section>
<section id="demo"><h2>05 / Kịch bản thuyết trình & luyện phản biện</h2><div class="grid"><div class="panel"><h3>Anh Thư · 4–5 phút</h3><ol><li>Nêu bài toán và public/shared.</li><li>Đăng nhập, chọn địa chỉ và lấy quote.</li><li>Mở orders.php: quote_id, idempotency.</li><li>Checkout và giải thích IPN mới xác nhận tiền.</li><li>Theo dõi; demo quá cân hoặc quote hết hạn.</li></ol></div><div class="panel"><h3>Nhi · 4–5 phút</h3><ol><li>Hồ sơ/KYC và availability.</li><li>Xem/nhận offer, giải thích race.</li><li>Pickup → start → arrival → ảnh → complete.</li><li>Nêu nhánh hủy/hoàn và điểm.</li><li>Phân biệt earning với payout đã trả.</li></ol></div><div class="panel"><h3>Minh Anh · 4–5 phút</h3><ol><li>Dashboard và rào permission.</li><li>Duyệt KYC, xem đơn/ticket.</li><li>Policy và snapshot lịch sử.</li><li>Payment/refund/payout: đối soát đúng chứng từ.</li><li>Mở audit/job logs; nêu giới hạn nghiệm thu.</li></ol></div></div><div class="notice"><b>Bốn câu nhóm phải thống nhất</b><p>1. Stack nào đang bảo vệ? → Bản PHP trong repo này.<br>2. Ai phụ trách gì? → Theo tên trong doc, phân biệt UI với ownership backend.<br>3. Tiền đã trả chưa? → Đọc PAID/SUCCEEDED và chứng từ, không dựa PROCESSING hoặc redirect.<br>4. Test nào là thật? → Tách fixture/local khỏi provider/hosting; không nói đã nghiệm thu nếu chưa có bằng chứng.</p></div></section>
<section id="sources"><h2>06 / Nguồn tra cứu</h2><p>Code link cố định theo commit <code>{REV}</code> ở local khi soạn. Nếu commit chưa được push hoặc repo riêng tư, người nhận cần quyền repo/bản source tương ứng; đường dẫn file vẫn ghi rõ trong tên nguồn. Các đáp án đã được đọc từ source local; không khẳng định đã kiểm quyền truy cập GitHub của người nhận.</p><p>Tài liệu API bên ngoài dùng cho khái niệm/hợp đồng provider; hành vi riêng của SOMI lấy từ code và contract repo. Nội dung diễn giải để ôn tập, không chép nguyên tài liệu nhà cung cấp.</p><ul class="sources">{sourcehtml}</ul></section>
<footer>Soạn ngày 15/11/2026 (Asia/Saigon). Không thay đổi báo cáo Google Docs, không gọi thanh toán/gửi email và không chạy lại các bộ test nghiệp vụ khi soạn. Chia sẻ: gửi nguyên file HTML qua Drive/Zalo/email; tải về rồi mở Chrome/Edge. File này là tài liệu offline, chưa phải URL HTTP công khai.</footer></main><script>{script}</script></body></html>'''
OUT.write_text(doc, encoding='utf-8')
